import{_ as t,g as a,e as r,a4 as o}from"./chunks/framework.CEYJDsBW.js";const u=JSON.parse('{"title":"Projecting Templates from Body Text or Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/ageratum/26.1/packs/export.md","filePath":"en/ageratum/26.1/packs/export.md"}'),n={name:"en/ageratum/26.1/packs/export.md"};function c(i,e,s,d,m,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="projecting-templates-from-body-text-or-commands" tabindex="-1">Projecting Templates from Body Text or Commands <a class="header-anchor" href="#projecting-templates-from-body-text-or-commands" aria-label="Permalink to &quot;Projecting Templates from Body Text or Commands&quot;">​</a></h1><p>To project the same structure with the client command, place the compressed binary template at <code>assets/workshop/ageratum/stands/basic.nbt</code>. After pressing F3+T, run the following command in-game:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ageratum structure workshop:stands/basic ~ ~ ~</span></span></code></pre></div><p>The command index only scans <code>.nbt</code> files under <code>ageratum/</code>, stripping the folder prefix and extension to form the template ID. This differs from the direct resource path used by the <code>structure</code> tag in body text. The template manager receives raw NBT during client reload and loads it into a <code>StructureTemplate</code> using the current world&#39;s block registry when an actual projection request arrives. Templates cannot be instantiated before entering a world. <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/structure/AgeratumStructureTemplateManager.java" target="_blank" rel="noreferrer">Template registration &amp; lazy loading</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/command/AgeratumCommand.java" target="_blank" rel="noreferrer">Projection command</a></p><h2 id="getting-a-projection-from-the-preview-card" tabindex="-1">Getting a Projection from the Preview Card <a class="header-anchor" href="#getting-a-projection-from-the-preview-card" aria-label="Permalink to &quot;Getting a Projection from the Preview Card&quot;">​</a></h2><p>Open a page containing <code>&lt;structure&gt;</code> and click the project button. The component passes the current template to <code>StructureProjectionApi.showFloating</code>, displaying a floating projection in front of the local player. In this branch, no server disk-write is triggered here and there is no guide-specific export directory. To distribute structures, place existing NBT files directly at the resource path above. <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDNBTStructureComponent.java" target="_blank" rel="noreferrer">Page button</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/structure/StructureProjectionApi.java" target="_blank" rel="noreferrer">Projection API</a></p>',6)])])}const g=t(n,[["render",c]]);export{u as __pageData,g as default};
